#!/bin/bash
# Generated by cosy-lab — 仅作配置草稿，默认不要直接在生产机跑满 epoch
set -euo pipefail
export CUDA_VISIBLE_DEVICES="0"
pretrained_model_dir="/home/apc/xny/dialect-speech-platform/voice-engine/.runtime/models/Fun-CosyVoice3-0.5B-2512"
train_engine="torch_ddp"
num_gpus=$(echo "$CUDA_VISIBLE_DEVICES" | awk -F "," '{print NF}')
job_id=1986
dist_backend="nccl"
num_workers=2
prefetch=100

# 数据准备提示：参考 examples/libritts/cosyvoice3/run.sh stage 0~3
# prepare instruct 前缀: You are a helpful assistant.<|endofprompt|>

for model in llm; do
  torchrun --nnodes=1 --nproc_per_node=$num_gpus \
      --rdzv_id=$job_id --rdzv_backend="c10d" --rdzv_endpoint="localhost:1234" \
    ../../../cosyvoice/bin/train.py \
    --train_engine $train_engine \
    --config "/home/apc/xny/dialect-speech-platform/dialect-assets/wenchang/train/exports/20261123-114627_smoke_export/cosyvoice3.override.yaml" \
    --train_data "data/train.data.list" \
    --cv_data "data/dev.data.list" \
    --qwen_pretrain_path "$pretrained_model_dir/CosyVoice-BlankEN" \
    --onnx_path "$pretrained_model_dir" \
    --model $model \
    --checkpoint "$pretrained_model_dir/$model.pt" \
    --model_dir "/home/apc/xny/dialect-speech-platform/dialect-assets/wenchang/train/exports/20261123-114627_smoke_export/exp/$model/$train_engine" \
    --tensorboard_dir "/home/apc/xny/dialect-speech-platform/dialect-assets/wenchang/train/exports/20261123-114627_smoke_export/tensorboard/$model/$train_engine" \
    --ddp.dist_backend $dist_backend \
    --num_workers $num_workers \
    --prefetch $prefetch \
    --pin_memory --use_amp   \
    --deepspeed_config "/home/apc/xny/dialect-speech-platform/dialect-assets/wenchang/train/exports/20261123-114627_smoke_export/ds_stage2.json" \
    --deepspeed.save_states model+optimizer
done
